package com.google.javascript.rhino.jstype;

import com.google.javascript.rhino.ErrorReporter;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.jstype.JSTypeRegistry.ResolveMode;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Comparator;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for JSType.getTypesUnderShallowInequality.
 */
public class JSType_getTypesUnderShallowInequality_TriageGen1Test {

    @Test
    public void testUnionTypeSwapsOrder() {
        // Mock 'this' as a regular type
        JSType thisType = mock(JSType.class);
        when(thisType.isNullType()).thenReturn(false);
        when(thisType.isVoidType()).thenReturn(false);

        // Mock 'that' as a UnionType
        UnionType unionType = mock(UnionType.class);
        JSType typeA = mock(JSType.class);
        JSType typeB = mock(JSType.class);
        TypePair innerPair = new TypePair(typeA, typeB);

        // The method calls that.getTypesUnderShallowInequality(this)
        // Note: In the real implementation, UnionType is a subclass of JSType
        when(unionType.getTypesUnderShallowInequality(thisType)).thenReturn(innerPair);

        TypePair result = thisType.getTypesUnderShallowInequality(unionType);

        // The implementation for UnionType returns new TypePair(p.typeB, p.typeA)
        assertEquals(typeB, result.typeA);
        assertEquals(typeA, result.typeB);
    }

    @Test
    public void testNullTypeEqualityReturnsNullPair() {
        JSType thisType = mock(JSType.class);
        when(thisType.isNullType()).thenReturn(true);
        when(thisType.isVoidType()).thenReturn(false);

        JSType thatType = mock(JSType.class);
        when(thatType.isNullType()).thenReturn(true);
        when(thatType.isVoidType()).thenReturn(false);

        TypePair result = thisType.getTypesUnderShallowInequality(thatType);

        assertNull(result.typeA);
        assertNull(result.typeB);
    }

    @Test
    public void testVoidTypeEqualityReturnsNullPair() {
        JSType thisType = mock(JSType.class);
        when(thisType.isNullType()).thenReturn(false);
        when(thisType.isVoidType()).thenReturn(true);

        JSType thatType = mock(JSType.class);
        when(thatType.isNullType()).thenReturn(false);
        when(thatType.isVoidType()).thenReturn(true);

        TypePair result = thisType.getTypesUnderShallowInequality(thatType);

        assertNull(result.typeA);
        assertNull(result.typeB);
    }

    @Test
    public void testDifferentTypesReturnsOriginalTypes() {
        // Test case where neither is Null nor Void equality
        JSType thisType = mock(JSType.class);
        when(thisType.isNullType()).thenReturn(false);
        when(thisType.isVoidType()).thenReturn(false);

        JSType thatType = mock(JSType.class);
        when(thatType.isNullType()).thenReturn(false);
        when(thatType.isVoidType()).thenReturn(false);

        TypePair result = thisType.getTypesUnderShallowInequality(thatType);

        assertEquals(thisType, result.typeA);
        assertEquals(thatType, result.typeB);
    }

    @Test
    public void testNullAndVoidMismatchReturnsOriginalTypes() {
        // this is Null, that is Void -> should not trigger the (null, null) return
        JSType thisType = mock(JSType.class);
        when(thisType.isNullType()).thenReturn(true);
        when(thisType.isVoidType()).thenReturn(false);

        JSType thatType = mock(JSType.class);
        when(thatType.isNullType()).thenReturn(false);
        when(thatType.isVoidType()).thenReturn(true);

        TypePair result = thisType.getTypesUnderShallowInequality(thatType);

        assertEquals(thisType, result.typeA);
        assertEquals(thatType, result.typeB);
    }

    /**
     * Interface to allow mocking UnionType since it's a specific subclass.
     */
    private interface UnionType extends JSType {
        @Override
        TypePair getTypesUnderShallowInequality(JSType that);
    }
}
